  (forall c0 n p, PM.p_tb s = PM.VLong c0 n p -> PMFA.agA M M' p c0) ->
  PM.parser_at RSEGS PeCLayoutA.CADDR_A PMSPA.accA PMSPA.annA M' op ois (push_st s b' k' c).
